svg.script:
(function(){
  var root = document.querySelector('.a6p7-root');
  if(!root){
    var scripts = document.getElementsByTagName('script');
    var s = scripts[scripts.length-1];
    root = s && s.ownerSVGElement ? s.ownerSVGElement : null;
  }
  if(!root) return;

  function Q(sel){ return root.querySelector(sel); }
  var tip = Q('#a6p7-tip');
  var statusEl = Q('#a6p7-status');
  var liveEl = Q('#a6p7-live');
  var resetBtn = Q('#a6p7-btn-reset');
  var reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch(e){ reduce = false; }

  var labels = {
    eixo: {
      tip1: 'Eixo = idade',
      tip2: 'Etiologia preferencial muda com a faixa etária',
      stroke: 'var(--a6p7-indigo, #818CF8)',
      status: 'Eixo etário · condutas diferentes',
      live: 'Para o generalista e a prova, a idade é o eixo preferencial de etiologia da crise.',
      mode: 'eixo'
    },
    neo: {
      tip1: 'Neonato · alarme',
      tip2: 'Crise NÃO é fisiológica — investigar',
      stroke: 'var(--a6p7-coral, #F87171)',
      status: 'Neonato · algo está errado',
      live: 'No neonato, crise pede investigação: metabólico, infecção congênita, malformação, anóxia periparto.',
      mode: 'neo'
    },
    feb: {
      tip1: '6 meses – 5 anos',
      tip2: 'Crise febril lidera · NÃO é epilepsia',
      stroke: 'var(--a6p7-gold, #FBBF24)',
      status: 'Febril · selo NÃO é epilepsia',
      live: 'Nesta faixa a crise febril é o grande motivo. Continua sendo causa importante de crise na infância — sem virar epilepsia.',
      mode: 'feb'
    },
    metab: {
      tip1: 'Metabólico',
      tip2: 'Causa a investigar no neonato com crise',
      stroke: 'var(--a6p7-coral, #F87171)',
      status: 'Investigar · metabólico',
      live: 'Neonato com crise: erro metabólico entra no rol — não normalizar o evento.',
      mode: 'neo'
    },
    inf: {
      tip1: 'Infecção congênita',
      tip2: 'Causa a investigar no neonato com crise',
      stroke: 'var(--a6p7-coral, #F87171)',
      status: 'Investigar · infecção congênita',
      live: 'Infecção congênita é hipótese de trabalho no neonato com crise — alarme, não rotina.',
      mode: 'neo'
    },
    mal: {
      tip1: 'Malformação',
      tip2: 'Causa a investigar no neonato com crise',
      stroke: 'var(--a6p7-coral, #F87171)',
      status: 'Investigar · malformação',
      live: 'Malformação do SNC pode se apresentar com crise no período neonatal.',
      mode: 'neo'
    },
    anox: {
      tip1: 'Anóxia periparto',
      tip2: 'Causa a investigar no neonato com crise',
      stroke: 'var(--a6p7-coral, #F87171)',
      status: 'Investigar · anóxia periparto',
      live: 'Anóxia periparto compõe o alarme neonatal — crise aqui não é “coisa de nascença normal”.',
      mode: 'neo'
    },
    nao: {
      tip1: 'NÃO é epilepsia',
      tip2: 'Crise febril carrega o selo duro',
      stroke: 'var(--a6p7-gold, #FBBF24)',
      status: 'Selo · febril ≠ epilepsia',
      live: 'Crise febril não é epilepsia. O recorte para aqui — sem abrir simples × complexa.',
      mode: 'feb'
    }
  };

  function setMode(mode){
    if(!mode){
      root.removeAttribute('data-mode');
      root.setAttribute('data-playing','0');
      return;
    }
    root.setAttribute('data-mode', mode);
    if(!reduce && (mode === 'neo' || mode === 'feb')){
      root.setAttribute('data-playing','1');
    } else {
      root.setAttribute('data-playing','0');
    }
  }

  function clientToSvg(cx, cy){
    var pt = root.createSVGPoint();
    pt.x = cx; pt.y = cy;
    var m = root.getScreenCTM();
    if(!m) return {x:cx, y:cy};
    var p = pt.matrixTransform(m.inverse());
    return {x:p.x, y:p.y};
  }

  function showTip(cx, cy, t1, t2, stroke){
    if(!tip) return;
    var t1el = Q('#a6p7-tip-t1');
    var t2el = Q('#a6p7-tip-t2');
    var bg = Q('#a6p7-tip-bg');
    if(t1el) t1el.textContent = t1;
    if(t2el) t2el.textContent = t2;
    if(bg) bg.setAttribute('stroke', stroke || 'var(--a6p7-gold, #FBBF24)');
    var p = clientToSvg(cx, cy);
    var w = 310, h = 58, off = 14;
    var x = p.x + off;
    var y = p.y + off;
    if(x + w > 820) x = p.x - w - off;
    if(y + h > 600) y = p.y - h - off;
    if(x < 8) x = 8;
    if(y < 8) y = 8;
    tip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    tip.setAttribute('opacity', '1');
  }

  function hideTip(){
    if(tip) tip.setAttribute('opacity', '0');
  }

  function applyLabel(key, cx, cy){
    var L = labels[key];
    if(!L) return;
    setMode(L.mode);
    if(cx != null && cy != null) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
    if(statusEl){
      statusEl.textContent = L.status;
      statusEl.setAttribute('fill', L.stroke);
    }
    if(liveEl) liveEl.textContent = L.live;
  }

  function bindHotspot(el, key){
    if(!el) return;
    var L = labels[key];
    function activate(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 20;
      applyLabel(key, cx, cy);
    }
    el.addEventListener('mouseenter', function(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      applyLabel(key, ev.clientX, ev.clientY);
    });
    el.addEventListener('mousemove', function(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      if(tip && tip.getAttribute('opacity') === '1' && L){
        showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
      }
    });
    el.addEventListener('mouseleave', function(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      hideTip();
    });
    el.addEventListener('click', activate);
    el.addEventListener('focus', function(){
      var b = el.getBoundingClientRect();
      applyLabel(key, b.left + b.width/2, b.top + b.height/2);
    });
    el.addEventListener('blur', function(){ hideTip(); });
    el.addEventListener('keydown', function(ev){
      if(ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar'){
        ev.preventDefault();
        activate(ev);
      }
    });
  }

  bindHotspot(Q('#a6p7-hs-neo'), 'neo');
  bindHotspot(Q('#a6p7-hs-feb'), 'feb');
  bindHotspot(Q('#a6p7-hs-metab'), 'metab');
  bindHotspot(Q('#a6p7-hs-inf'), 'inf');
  bindHotspot(Q('#a6p7-hs-mal'), 'mal');
  bindHotspot(Q('#a6p7-hs-anox'), 'anox');
  bindHotspot(Q('#a6p7-hs-nao'), 'nao');
  bindHotspot(Q('#a6p7-chip-eixo'), 'eixo');
  bindHotspot(Q('#a6p7-chip-neo'), 'neo');
  bindHotspot(Q('#a6p7-chip-feb'), 'feb');
  bindHotspot(Q('#a6p7-seal'), 'nao');

  if(resetBtn){
    function doReset(){
      setMode(null);
      hideTip();
      if(statusEl){
        statusEl.textContent = 'Toque o neonato · a faixa febril · ou o selo NÃO';
        statusEl.setAttribute('fill', 'var(--a6p7-muted, #94A3B8)');
      }
      if(liveEl){
        liveEl.textContent = 'Idade decide a hipótese: alarme no início da vida; febril no pré-escolar com selo duro.';
      }
    }
    resetBtn.addEventListener('click', doReset);
    resetBtn.addEventListener('keydown', function(ev){
      if(ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar'){
        ev.preventDefault();
        doReset();
      }
    });
  }

  root.setAttribute('data-playing','0');
})();
